begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into app.actors(id,workos_user_id,primary_email) values('b1000000-0000-4000-8000-000000000001','request_fixture','request@fixture.example'),('b1000000-0000-4000-8000-000000000002','request_other','other@fixture.example');
insert into app.categories(slug,name) values('fixture-category','Fixture Category');
select set_config('request.jwt.claims','{"sub":"request_fixture"}',true);
set local role authenticated;
select extensions.is(public.request_business_listing('{"name":"Synthetic Shop","citySlug":"reno","categorySlug":"fixture-category","phone":"+17755550100","zip":"89502","description":"Synthetic repair service.","website":"https://fixture.example"}','request-fixture-key')->>'status','pending_review','new listing request saves for human review');
select extensions.is(public.request_business_listing('{"name":"Synthetic Shop","citySlug":"reno","categorySlug":"fixture-category","phone":"+17755550100","zip":"89502","description":"Synthetic repair service.","website":"https://fixture.example"}','request-fixture-key')->>'idempotent','true','request replay is idempotent');
select extensions.throws_ok($$select public.request_business_listing('{"name":"Synthetic Shop","citySlug":"sparks","categorySlug":"fixture-category","phone":"+17755550100","zip":"89431","description":"Synthetic repair service."}','outside-request-key')$$,'P0001','invalid_listing_request','new requests cannot expand the Reno pilot');
select extensions.throws_ok($$select public.request_business_listing('{"name":"Synthetic Shop","citySlug":"reno","categorySlug":"fixture-category","phone":"+17755550100","zip":"89502","description":"Synthetic repair service.","street":"private residence"}','private-street-key')$$,'P0001','invalid_listing_request','private street cannot enter request payload');
reset role;
select extensions.is((select count(*)::integer from app.listing_requests where actor_id='b1000000-0000-4000-8000-000000000001'),1,'one durable request');
select extensions.is((select count(*)::integer from app.listing_participations where actor_id='b1000000-0000-4000-8000-000000000001'),0,'listing request grants no participation');
select extensions.ok(not has_table_privilege('authenticated','app.listing_requests','select'),'request rows private to guarded review');
select extensions.ok(not has_function_privilege('authenticated','public.purge_expired_claim_evidence()','execute'),'claimant cannot run retention purge');
select set_config('request.jwt.claims','{"sub":"request_other"}',true);
set local role authenticated;
select extensions.throws_ok($$select public.request_business_listing('{"name":"Synthetic Shop","citySlug":"reno","categorySlug":"fixture-category","phone":"+17755550100","zip":"89502","description":"Synthetic repair service.","website":"https://fixture.example"}','request-fixture-key')$$,'P0001','idempotency_conflict','other user cannot reuse request key');
reset role;
insert into app.businesses(id,canonical_name) values('b2000000-0000-4000-8000-000000000001','Retention Fixture');
insert into app.business_listings(id,business_id,current_slug,display_name,city_slug,postal_code) values('b3000000-0000-4000-8000-000000000001','b2000000-0000-4000-8000-000000000001','retention-fixture','Retention Fixture','reno','89502');
insert into app.claims(id,claimant_actor_id,listing_id,method,status) values('b4000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000001','document','needs_evidence');
insert into private.claim_evidence(id,claim_id,reference,explanation,idempotency_key,challenge,expires_at,delete_after) values('b5000000-0000-4000-8000-000000000001','b4000000-0000-4000-8000-000000000001','Synthetic registry reference','Private synthetic narrative requiring retention','retention-fixture-key',extensions.gen_random_uuid(),statement_timestamp()-interval '1 day',statement_timestamp()-interval '1 day');
insert into private.claim_authority_reviews(id,evidence_id,listing_id,claimant_actor_id,reviewed_role,reviewer_id,identity_basis,authority_basis,conflict_resolution,scope_snapshot,valid_until,delete_after) values('b6000000-0000-4000-8000-000000000001','b5000000-0000-4000-8000-000000000001','b3000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','business_owner','b1000000-0000-4000-8000-000000000002','Synthetic private identity notes','Synthetic private authority notes','Synthetic private conflict notes','{}',statement_timestamp()-interval '1 day',statement_timestamp()-interval '1 day');
select extensions.is(public.purge_expired_claim_evidence(),2,'purge removes both expired proof narrative and private review content');
select extensions.ok((select reference is null and explanation is null and deleted_at is not null and revoked_at is not null from private.claim_evidence where id='b5000000-0000-4000-8000-000000000001'),'expired evidence content is removed with deletion receipt');
select extensions.ok((select identity_basis is null and authority_basis is null and conflict_resolution is null and redacted_at is not null and content_sha256 ~ '^[a-f0-9]{64}$' from private.claim_authority_reviews where id='b6000000-0000-4000-8000-000000000001'),'private assessment content removed; hash and metadata retained');
select extensions.is(public.purge_expired_claim_evidence(),0,'retention replay is idempotent');
select extensions.is((select count(*)::integer from app.audit_events where action in ('claim.evidence_deleted','claim.review_content_redacted')),2,'each retained deletion/redaction is auditable');
select * from extensions.finish();
rollback;
